# buildtest.cmd.civet

import {EXEC, assert, defined} from 'base'
import {stdChecks, o} from 'llutils'
import {nonOption, allNonOptions, getFlags} from 'cmd-args'
import {withExt, findFile} from 'fsys'
import {procFiles, procOneFile, doInstallCmd} from 'exec'
import {doUnitTest} from 'typescript'
import {doCompileCivet} from 'civet'

stdChecks "buildutest -nf (all | <stub>*)"

// ---------------------------------------------------------------------------

EXEC () =>
	# --- echoes if flag is set
	{force} := getFlags {
		force: 'f'
		}
	if (nonOption(0) == 'all')
		await procFiles [doCompileCivet, ['**/*.test.civet']], {force}
	else
		for stub of allNonOptions()
			fileName := "#{stub}.test.civet"
			path := findFile fileName
			assert defined(path), "No such file: #{fileName}"
			await procOneFile path, doCompileCivet, {force}

# hera-compile.lib.test.civet

import {esc} from 'unicode'
import {s2} from 'llutils'
import {
	doCompileHera, preprocHera, testHeraCode,
	} from 'hera-compile'
import {
	equal, truthy, falsy, succeeds, fails,
	} from 'unit-test'

# ---------------------------------------------------------------------------

equal await testHeraCode("""
	name := 'John Deighan'
	lItems: string[] := []

	#beginParse
		lItems.length = 0

	Main
		/abc/
	"""), s2"""
	```
	import {CParseMatches} from 'parse-utils';
	export let pm = new CParseMatches();

	const name = 'John Deighan'
	const lItems: string[] = []

	export const beginParse = (
			text: string,
			hOptions: {[key: string|symbol]: unknown} = {}
			): string|undefined => {
		pm.reset(text);
		lItems.length = 0
		}
	```

	Main
		/abc/ ->
			pm.match('Main', $loc);

	"""

equal await testHeraCode("""
	name := 'John Deighan'
	lItems: string[] := []

	#beginParse
		lItems.length = 0

	Main
		/abc/ Next
			lItems.push 'main'

	Next
		"xyz"
			lItems.push 'done'
	"""), s2"""
	```
	import {CParseMatches} from 'parse-utils';
	export let pm = new CParseMatches();

	const name = 'John Deighan'
	const lItems: string[] = []

	export const beginParse = (
			text: string,
			hOptions: {[key: string|symbol]: unknown} = {}
			): string|undefined => {
		pm.reset(text);
		lItems.length = 0
		}
	```

	Main
		/abc/ Next ->
			pm.match('Main', $loc);
			lItems.push('main')

	Next
		"xyz" ->
			pm.match('Next', $loc);
			lItems.push('done')
	"""
